'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var instanceOf = require( '@stdlib/assert/instance-of' );
var Float32Array = require( '@stdlib/array/float32' );
var Float64Array = require( '@stdlib/array/float64' );
var realf = require( '@stdlib/complex/float32/real' );
var imagf = require( '@stdlib/complex/float32/imag' );
var real = require( '@stdlib/complex/float64/real' );
var imag = require( '@stdlib/complex/float64/imag' );
var reinterpret64 = require( '@stdlib/strided/base/reinterpret-complex64' );
var reinterpret128 = require( '@stdlib/strided/base/reinterpret-complex128' );
var factory = require( './../lib' );


// FUNCTIONS //

/**
* Comparison function for complex128 values.
*
* @private
* @param {Complex128} a - first value for comparison
* @param {Complex128} b - second value for comparison
* @returns {number} comparison result
*/
function compareFcn128( a, b ) {
	var re1;
	var re2;
	var im1;
	var im2;
	re1 = real( a );
	re2 = real( b );
	if ( re1 < re2 ) {
		return -1;
	}
	if ( re1 > re2 ) {
		return 1;
	}
	im1 = imag( a );
	im2 = imag( b );
	if ( im1 < im2 ) {
		return -1;
	}
	if ( im1 > im2 ) {
		return 1;
	}
	return 0;
}

/**
* Comparison function for complex64 values.
*
* @private
* @param {Complex64} a - first value for comparison
* @param {Complex64} b - second value for comparison
* @returns {number} comparison result
*/
function compareFcn64( a, b ) {
	var re1;
	var re2;
	var im1;
	var im2;
	re1 = realf( a );
	re2 = realf( b );
	if ( re1 < re2 ) {
		return -1;
	}
	if ( re1 > re2 ) {
		return 1;
	}
	im1 = imagf( a );
	im2 = imagf( b );
	if ( im1 < im2 ) {
		return -1;
	}
	if ( im1 > im2 ) {
		return 1;
	}
	return 0;
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof factory, 'function', 'main export is a function' );
	t.end();
});

tape( 'attached to the prototype of the returned constructor is a `sort` method (complex128)', function test( t ) {
	var Complex128Array = factory( 'complex128' );
	t.strictEqual( hasOwnProp( Complex128Array.prototype, 'sort' ), true, 'has property' );
	t.strictEqual( isFunction( Complex128Array.prototype.sort ), true, 'has method' );
	t.end();
});

tape( 'attached to the prototype of the returned constructor is a `sort` method (complex64)', function test( t ) {
	var Complex64Array = factory( 'complex64' );
	t.strictEqual( hasOwnProp( Complex64Array.prototype, 'sort' ), true, 'has property' );
	t.strictEqual( isFunction( Complex64Array.prototype.sort ), true, 'has method' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a complex number array instance (complex128)', function test( t ) {
	var Complex128Array;
	var values;
	var arr;
	var i;

	Complex128Array = factory( 'complex128' );
	arr = new Complex128Array( 5 );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.sort.call( value, compareFcn128 );
		};
	}
});

