tape( 'the method throws an error if provided a first argument which is not a function (complex128)', function test( t ) {
	var Complex128Array;
	var values;
	var arr;
	var i;

	Complex128Array = factory( 'complex128' );
	arr = new Complex128Array( 10 );

	values = [
		'5',
		3.14,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.sort( value );
		};
	}
});

